create table if not exists public.interview_lessons(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,excerpt text not null,category text not null check(category in('Personal Introduction','Family & Education','Motivation & Career','Current Affairs','Rapid Fire','Final Interview Strategy')),rich_content_json jsonb not null default '{"type":"doc","content":[]}'::jsonb,featured_image_path text not null,status text not null default 'draft' check(status in('draft','published')),author_id uuid references public.users(id) on delete set null,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.interview_lessons enable row level security;
create policy "Published interview lessons readable" on public.interview_lessons for select using(status='published' or exists(select 1 from public.users where id=auth.uid() and role='admin'));
create policy "Admins manage interview lessons" on public.interview_lessons for all using(exists(select 1 from public.users where id=auth.uid() and role='admin')) with check(exists(select 1 from public.users where id=auth.uid() and role='admin'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('interview-assets','interview-assets',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set allowed_mime_types=excluded.allowed_mime_types;
create policy "Authenticated read interview assets" on storage.objects for select to authenticated using(bucket_id='interview-assets');
create policy "Admins manage interview assets" on storage.objects for all to authenticated using(bucket_id='interview-assets' and exists(select 1 from public.users where id=auth.uid() and role='admin')) with check(bucket_id='interview-assets' and exists(select 1 from public.users where id=auth.uid() and role='admin'));
